/**
 * Docs' wire shapes, generated by Google from the API's Discovery document
 * (@googleapis/docs) rather than written here. Type-only: nothing of that
 * package runs. Every field is optional and may be null, because that is what
 * the schema promises. The one import in domain/, on purpose.
 */
import type { DeepReadonly } from "@foreverworks/mcp-kit";
import type { docs_v1 } from "@googleapis/docs";

export type RawDocument = DeepReadonly<docs_v1.Schema$Document>;
export type RawElement = DeepReadonly<docs_v1.Schema$StructuralElement>;
export type RawParagraph = DeepReadonly<docs_v1.Schema$Paragraph>;
export type RawParagraphElement = DeepReadonly<docs_v1.Schema$ParagraphElement>;
export type RawTextStyle = DeepReadonly<docs_v1.Schema$TextStyle>;
export type RawList = DeepReadonly<docs_v1.Schema$List>;
export type RawBatchUpdateResponse = DeepReadonly<docs_v1.Schema$BatchUpdateDocumentResponse>;
/** What this server SENDS, built as plain data and typed by the same schema. */
export type DocsRequest = DeepReadonly<docs_v1.Schema$Request>;
export type RawTextStyleOut = docs_v1.Schema$TextStyle;
export type RawTab = DeepReadonly<docs_v1.Schema$Tab>;
export type RawDocumentTab = DeepReadonly<docs_v1.Schema$DocumentTab>;
export type RawTable = DeepReadonly<docs_v1.Schema$Table>;
